n.update({'A0561-B0076':'伪装成希尔麾下战士的是阿尔法渗透者，不据此把希尔本人列为刺客。','A0561-B0078':'charged 此处为授命、责成，原译被亲自指控误判词义。原体是否战死按 seemingly 保留不确定性。','A0561-B0082':'intercede 为介入掩护，原译调解不合舰队战情；前段阵亡与本段再现均按身份难辨的原文叙述保留。','A0561-B0089':'原文对死亡使用 reportedly、apparently、it is believed 等限定；未将阿尔法原体死亡的传闻升级为定论。','A0561-B0091':'持续威胁舰船与据点的是阿尔法战帮，不是遭其攻击的军事目标。','A0561-B0107':'World Prince 按修饰关系暂译世界王子，原译王子世界颠倒词序；专名待官方核对。','A0561-B0123':'本篇年表太阳战争记010—015.M31，与0554的010—014.M31范围不同，保留源文版本差异。'})
